function sel(name,options,value,extra=''){return `<select name="${esc(name)}" ${extra}>${options.map(a=>{const [v,l]=Array.isArray(a)?a:[a,a];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`}
